import{_ as o,o as t,c as a,a4 as d}from"./chunks/framework.WdFb_vN1.js";const p=JSON.parse('{"title":"Accessibility (a11y)","description":"","frontmatter":{},"headers":[],"relativePath":"draggable/a11y.md","filePath":"draggable/a11y.md","lastUpdated":1789241665000}'),r={name:"draggable/a11y.md"};function l(c,e,n,i,s,u){return t(),a("div",null,e[0]||(e[0]=[d('<h1 id="accessibility-a11y" tabindex="-1">Accessibility (a11y) <a class="header-anchor" href="#accessibility-a11y" aria-label="Permalink to &quot;Accessibility (a11y)&quot;">​</a></h1><p>Polish notes for keyboard and assistive-tech support in <code>@hungpvq/draggable</code> shells (Vue + React parity).</p><p>Related: <a href="./stable-api.html">Stable API</a> · <a href="./context-menu.html">ContextMenu</a> · <a href="./css-tokens.html">CSS tokens</a></p><p><strong>SemVer:</strong> Escape-to-close when focus is inside a Stable panel shell is part of the documented contract (additive <strong>minor</strong> behavior). See skill <code>draggable-semver-api</code>.</p><h2 id="panel-contracts-by-type" tabindex="-1">Panel contracts by type <a class="header-anchor" href="#panel-contracts-by-type" aria-label="Permalink to &quot;Panel contracts by type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Panel</th><th>Role</th><th>Modal?</th><th>Escape</th><th>Focus on open</th><th>Tab trap</th><th>Background inert</th></tr></thead><tbody><tr><td>Modal</td><td><code>dialog</code> + <code>aria-modal=&quot;true&quot;</code></td><td>yes</td><td>closes</td><td><code>focusFirst</code></td><td>yes (<code>trapTabKey</code>)</td><td>yes (<code>setModalSiblingsInert</code>)</td></tr><tr><td>Popup</td><td><code>dialog</code> (non-modal)</td><td>no</td><td>closes if focus in panel</td><td><code>focusFirst</code></td><td>yes (<code>trapTabKey</code>)</td><td>no (map stays usable)</td></tr><tr><td>Float</td><td><code>dialog</code> (non-modal)</td><td>no</td><td>closes if focus in panel</td><td><code>focusFirst</code></td><td>no</td><td>no</td></tr><tr><td>Drawer</td><td><code>dialog</code> (non-modal)</td><td>no</td><td>closes if focus in panel*</td><td><code>focusFirst</code></td><td>no</td><td>no</td></tr><tr><td>Sidebar</td><td><code>complementary</code></td><td>no</td><td>closes if focus in shell*</td><td><code>focusFirst</code></td><td>no</td><td>no</td></tr><tr><td>Bottom</td><td><code>region</code></td><td>no</td><td>closes if focus in shell*</td><td><code>focusFirst</code></td><td>no</td><td>no</td></tr></tbody></table><p>*Escape is ignored while a switcher <strong>ContextMenu</strong> is open (<code>menuOpen</code>), so Esc closes the menu first.</p><p>All titled shells prefer <code>aria-labelledby</code> pointing at the title host; bottom keeps <code>aria-label=&quot;Bottom panel&quot;</code> as a fallback name. Panel roots use <code>tabindex=&quot;-1&quot;</code> so they can receive focus when needed. On close, shells call <code>restoreFocus</code> to the opener.</p><p>Icon-only chrome (<code>DragButton</code> — internal, not a public export): native <code>disabled</code> + descriptive <code>aria-label</code>; expand toggles also set <code>aria-expanded</code> (and <code>aria-controls</code> where a content host id exists). Decorative header rules use <code>aria-hidden=&quot;true&quot;</code>. Do not confuse with map-core <code>MapControlButton</code>.</p><h2 id="modal-draggablemodal" tabindex="-1">Modal (<code>DraggableModal</code>) <a class="header-anchor" href="#modal-draggablemodal" aria-label="Permalink to &quot;Modal (`DraggableModal`)&quot;">​</a></h2><ul><li><code>role=&quot;dialog&quot;</code> + <code>aria-modal=&quot;true&quot;</code> + <code>aria-labelledby</code> (header title id)</li><li>Focus moves into the dialog on open; <strong>restored</strong> to the previously focused element on close</li><li><strong>Tab</strong> / <strong>Shift+Tab</strong> trapped inside the dialog (<code>trapTabKey</code>)</li><li><strong>Escape</strong> closes</li><li>Background siblings under <code>.draggable-root</code> get <code>inert</code> + <code>aria-hidden</code> while open (reference-counted for nested modals)</li></ul><h2 id="popup-float" tabindex="-1">Popup / float <a class="header-anchor" href="#popup-float" aria-label="Permalink to &quot;Popup / float&quot;">​</a></h2><ul><li>Non-modal <code>role=&quot;dialog&quot;</code> + <code>aria-labelledby</code> + <code>tabindex=&quot;-1&quot;</code></li><li>Expand control: <code>aria-expanded</code>; Close / Bring forward / Send back labeled</li><li>Escape closes when focus is inside the panel; focus restored on close</li><li><strong>Popup</strong> uses <code>trapTabKey</code> (Tab cycles within the panel). Float does <strong>not</strong> use <code>setModalSiblingsInert</code> or a mandatory tab trap.</li><li>Does <strong>not</strong> use <code>setModalSiblingsInert</code></li></ul><h2 id="drawer" tabindex="-1">Drawer <a class="header-anchor" href="#drawer" aria-label="Permalink to &quot;Drawer&quot;">​</a></h2><ul><li>Non-modal <code>role=&quot;dialog&quot;</code> + <code>aria-labelledby</code></li><li>Switcher (when multiple drawers on an edge): <code>aria-haspopup=&quot;menu&quot;</code>, <code>aria-expanded</code>, ContextMenu <code>ariaLabel</code> / open-change</li><li>Escape + focus restore as in the table above</li><li>Resize handle is decorative for AT (<code>aria-hidden</code>)</li></ul><h2 id="sidebar-bottom" tabindex="-1">Sidebar / bottom <a class="header-anchor" href="#sidebar-bottom" aria-label="Permalink to &quot;Sidebar / bottom&quot;">​</a></h2><ul><li>Sidebar: <code>role=&quot;complementary&quot;</code> + <code>aria-labelledby</code></li><li>Bottom: <code>role=&quot;region&quot;</code> + <code>aria-labelledby</code> / <code>aria-label</code>; <code>aria-hidden</code> when not visible; expand sets <code>aria-controls</code> to the content host</li><li>Switcher triggers: <code>aria-haspopup=&quot;menu&quot;</code> + <code>aria-expanded</code></li><li>Escape + focus restore as in the table above</li></ul><h2 id="context-menu-experimental" tabindex="-1">Context menu (experimental) <a class="header-anchor" href="#context-menu-experimental" aria-label="Permalink to &quot;Context menu (experimental)&quot;">​</a></h2><ul><li><code>role=&quot;menu&quot;</code> + <code>aria-orientation=&quot;vertical&quot;</code> + <code>aria-label</code> (prop: Vue <code>ariaLabel</code> / React <code>ariaLabel</code>, default <code>&quot;Context menu&quot;</code>)</li><li>Open/close notify: Vue <code>@update:open</code>, React <code>onOpenChange(open)</code></li><li>Items: <code>role=&quot;menuitem&quot;</code>, <code>aria-disabled</code>, <code>aria-current</code> when <code>active</code></li><li>Wrap list markup as <code>&lt;ul class=&quot;context-menu&quot; role=&quot;presentation&quot;&gt;</code> so the outer <code>menu</code> role owns the structure</li><li><strong>Escape</strong> closes and <strong>restores focus</strong> to the opener (<code>restoreFocus</code>)</li><li><strong>Tab</strong> / <strong>Shift+Tab</strong> cycle <code>role=&quot;menuitem&quot;</code> nodes (<code>getMenuItems</code>; falls back to <code>trapTabKey</code> if none)</li><li>Arrow <strong>Up/Down</strong> (and Left/Right aliases), <strong>Home/End</strong>, <strong>Enter/Space</strong> via <code>handleMenuKeydown</code></li><li><strong>Typeahead</strong>: printable characters jump to the next matching label (buffer resets after 500ms; <code>clearMenuTypeahead</code> on close)</li></ul><h2 id="managementcontrol-experimental" tabindex="-1">ManagementControl (experimental) <a class="header-anchor" href="#managementcontrol-experimental" aria-label="Permalink to &quot;ManagementControl (experimental)&quot;">​</a></h2><p>Light a11y only: section titles as headings (<code>h3</code>), icon actions with <code>aria-label</code> (+ <code>title</code>), list rows activatable via click or Enter/Space (<code>role=&quot;button&quot;</code>).</p><h2 id="core-helpers-stable" tabindex="-1">Core helpers (Stable) <a class="header-anchor" href="#core-helpers-stable" aria-label="Permalink to &quot;Core helpers (Stable)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Helper</th><th>Use</th></tr></thead><tbody><tr><td><code>getFocusableElements</code> / <code>focusFirst</code> / <code>restoreFocus</code></td><td>Focus management</td></tr><tr><td><code>trapTabKey</code></td><td>Dialog / menu tab cycle</td></tr><tr><td><code>setModalSiblingsInert</code></td><td>Background inert while modal open</td></tr><tr><td><code>getMenuItems</code> / <code>handleMenuKeydown</code> / <code>clearMenuTypeahead</code></td><td>Menu keyboard + typeahead</td></tr></tbody></table><p>Changing these helpers’ documented behavior is a <strong>SemVer</strong> decision — see <a href="./stable-api.html">stable-api.md</a> and skill <code>draggable-semver-api</code>.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Keyboard <strong>drag / resize</strong> of panels driven by <code>vue-draggable-resizable</code> / <code>react-rnd</code></li><li>ContextMenu <strong>submenus</strong>; typeahead for multi-locale collation beyond basic character match</li><li>Full WAI-ARIA <strong>menu-button</strong> <code>aria-controls</code> id wiring on every trigger (optional future; shells already expose content host ids where useful)</li></ul>',26)]))}const b=o(r,[["render",l]]);export{p as __pageData,b as default};
